<?= $this->extend('layouts/app') ?>
<?= $this->section('content') ?>
<?php $val=static fn($key)=>is_string($input[$key]??null)?$input[$key]:'';$base=[];foreach(['q','source','status','owner'] as $key){$base[$key]=$val($key);} ?>
<div class="page-heading"><div><div class="eyebrow">LEADS / PIPELINE</div><h1>Leads pipeline</h1><p>Drag an open lead to a stage, or use its Move controls. Each column shows at most 20 leads.</p></div><a class="btn btn-outline-light" href="<?= site_url('leads') ?>">List view</a></div>
<?= view('clients/alerts') ?><div id="pipeline-feedback" role="status" aria-live="polite" class="alert" hidden></div>
<form class="crm-card client-filters" method="get" action="<?= site_url('leads/kanban') ?>"><div><label for="pipeline-q">Search leads</label><input class="form-control" id="pipeline-q" name="q" maxlength="100" value="<?= esc($val('q')) ?>" placeholder="Name, code, email or phone"></div><?php foreach(['source'=>['Source',$sources],'status'=>['Status',$statuses]] as $key=>[$label,$items]): ?><div><label for="pipeline-<?= $key ?>"><?= $label ?></label><select class="form-select" id="pipeline-<?= $key ?>" name="<?= $key ?>"><option value="">All</option><?php foreach($items as $item): ?><option value="<?= (int)$item['id'] ?>" <?= $val($key)===(string)$item['id']?'selected':'' ?>><?= esc($item['name']) ?></option><?php endforeach ?></select></div><?php endforeach ?><?php if($user->can('leads.manageall')): ?><div><label for="pipeline-owner">Assigned user</label><select class="form-select" id="pipeline-owner" name="owner"><option value="">All</option><?php foreach($owners as $owner): ?><option value="<?= (int)$owner['id'] ?>" <?= $val('owner')===(string)$owner['id']?'selected':'' ?>><?= esc($owner['username']) ?></option><?php endforeach ?></select></div><?php endif ?><div class="client-actions"><button type="submit" class="btn btn-teal">Apply filters</button><a class="btn btn-outline-light" href="<?= site_url('leads/kanban') ?>">Reset</a></div></form>
<div class="kanban-board" tabindex="0" role="region" aria-label="Leads pipeline. Scroll horizontally to see more stages.">
<?php foreach($columns as $column):$status=$column['status'];$listing=$column['listing'];$canDrop=!(int)$status['reserved']&&in_array($status['outcome'],['open','lost'],true); ?>
<section class="kanban-column" data-status="<?= (int)$status['id'] ?>" data-drop="<?= $canDrop?'1':'0' ?>" aria-labelledby="stage-<?= (int)$status['id'] ?>"><div class="kanban-heading"><h2 id="stage-<?= (int)$status['id'] ?>"><?= esc($status['name']) ?></h2><span class="state-pill <?= $status['outcome']==='open'?'teal':'amber' ?>"><?= (int)$listing['total'] ?></span></div><p class="kanban-hint"><?= $status['outcome']==='converted'?'Completed through conversion only.':($status['outcome']==='lost'?'Lost leads need explicit authorized reopening.':'Open pipeline stage.') ?></p>
<div class="kanban-cards"><?php foreach($listing['rows'] as $lead):$editable=$lead['outcome']==='open'&&$policy->allows($user,'edit',$lead); ?>
<article class="kanban-card" data-lead="<?= (int)$lead['id'] ?>" data-version="<?= (int)$lead['version'] ?>" data-stage-url="<?= site_url('leads/'.$lead['id'].'/stage') ?>" draggable="<?= $editable?'true':'false' ?>"><h3><a href="<?= site_url('leads/'.$lead['id']) ?>"><?= esc($lead['display_name']) ?></a></h3><p><?= esc($lead['code']) ?> · <?= esc($lead['type']) ?></p><p><?= esc($lead['email']?:'No email') ?></p><p>Owner: <?= esc($lead['owner_name']) ?></p><p>Source: <?= esc($lead['source_name']) ?></p>
<?php if($editable): ?><form class="kanban-move" method="post" action="<?= site_url('leads/'.$lead['id'].'/stage') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$lead['version'] ?>"><label for="move-<?= (int)$lead['id'] ?>">Move <?= esc($lead['display_name']) ?> to</label><div><select id="move-<?= (int)$lead['id'] ?>" name="status_id" class="form-select" required><?php foreach($statuses as $destination):if((int)$destination['reserved']||!in_array($destination['outcome'],['open','lost'],true))continue; ?><option value="<?= (int)$destination['id'] ?>" <?= (int)$destination['id']===(int)$lead['status_id']?'selected':'' ?>><?= esc($destination['name']) ?></option><?php endforeach ?></select><button class="btn btn-outline-light" type="submit">Move</button></div></form><?php endif ?>
<?php if($lead['status_slug']==='qualified'&&$policy->allows($user,'convert',$lead)&&$user->can('clients.view')): ?><a class="subtle-link mt-3" href="<?= site_url('leads/'.$lead['id'].'/convert') ?>">Review conversion</a><?php endif ?></article><?php endforeach ?><?php if(!$listing['rows']): ?><p class="kanban-empty">No matching leads in this stage.</p><?php endif ?></div>
<nav class="kanban-pagination" aria-label="<?= esc($status['name']) ?> column pagination"><span>Page <?= $listing['page'] ?> / <?= $listing['pages'] ?></span><?php foreach([-1=>'Previous',1=>'Next'] as $offset=>$label):$page=$listing['page']+$offset;if($page<1||$page>$listing['pages'])continue;$pageArgs=[];foreach($columns as $other){$pageArgs[$other['status']['id']]=$other['listing']['page'];}$pageArgs[$status['id']]=$page; ?><a class="subtle-link" href="<?= esc(site_url('leads/kanban').'?'.http_build_query($base+['columns'=>$pageArgs])) ?>"><?= $label ?></a><?php endforeach ?></nav></section><?php endforeach ?></div>
